package com.example.arcana.entity;
import net.minecraft.world.entity.*; import net.minecraft.world.entity.projectile.AbstractArrow; import net.minecraft.world.level.Level; import net.minecraft.world.phys.*; import net.minecraft.nbt.CompoundTag; import net.minecraft.network.protocol.Packet; import net.minecraftforge.network.NetworkHooks; import net.minecraft.core.particles.ParticleTypes;
public class ArcanaBoltEntity extends AbstractArrow implements net.minecraft.world.entity.projectile.ItemSupplier { public static final net.minecraft.world.item.Item ITEM=net.minecraft.world.item.Items.AMETHYST_SHARD; public static final double BASE_RANGE_BLOCKS=32.0; private double startX,startY,startZ; public ArcanaBoltEntity(EntityType<? extends ArcanaBoltEntity> t,Level l){super(t,l);setNoGravity(true);} public ArcanaBoltEntity(Level l,LivingEntity o){this(ArcanaEntities.ARCANE_BOLT.get(),l);setOwner(o);} public void setPos(double x,double y,double z){super.setPos(x,y,z);if(tickCount==0){startX=x;startY=y;startZ=z;}} protected void doPostHurtEffects(LivingEntity e){e.hurt(damageSources().magic(),6);e.setDeltaMovement(e.getDeltaMovement().add(getDeltaMovement().normalize().scale(.25)));} public void tick(){super.tick();if(level().isClientSide)for(int i=0;i<3;i++)level().addParticle(ParticleTypes.END_ROD,getX(),getY(),getZ(),0,0,0);if(distanceToSqr(startX,startY,startZ)>=BASE_RANGE_BLOCKS*BASE_RANGE_BLOCKS)discard();} public net.minecraft.world.item.ItemStack getItem(){return new net.minecraft.world.item.ItemStack(ITEM);} public net.minecraft.world.item.ItemStack getPickupItem(){return new net.minecraft.world.item.ItemStack(ITEM);}}
